1	//! The write side of EBML for the WebM writer (spec §11 CX-15 (3)): the
2	//! element IDs it writes, the variable-length sizes, the element encoders and
3	//! the builders for every level-1 element but the Clusters, which
4	//! `webm_writer.rs` streams.
5	//!
6	//! Every builder answers whole bytes, so `webm_writer.rs` only places them.
7	//! IDs are written as the Matroska specification spells them (RFC 9559, RFC
8	//! 8794), marker bits included. A size is the shortest vint that holds it,
9	//! except where a size is patched later, which is always 8 bytes.
10	
11	use crate::container_codec::Mastering;
12	
13	// ---- element IDs -----------------------------------------------------------
14	
15	pub(crate) const EBML: u32 = 0x1A45_DFA3;
16	const EBML_VERSION: u32 = 0x4286;
17	const EBML_READ_VERSION: u32 = 0x42F7;
18	const EBML_MAX_ID_LENGTH: u32 = 0x42F2;
19	const EBML_MAX_SIZE_LENGTH: u32 = 0x42F3;
20	const DOC_TYPE: u32 = 0x4282;
21	const DOC_TYPE_VERSION: u32 = 0x4287;
22	const DOC_TYPE_READ_VERSION: u32 = 0x4285;
23	pub(crate) const SEGMENT: u32 = 0x1853_8067;
24	pub(crate) const SEEK_HEAD: u32 = 0x114D_9B74;
25	const SEEK: u32 = 0x4DBB;
26	const SEEK_ID: u32 = 0x53AB;
27	const SEEK_POSITION: u32 = 0x53AC;
28	pub(crate) const VOID: u32 = 0xEC;
29	pub(crate) const INFO: u32 = 0x1549_A966;
30	const TIMESTAMP_SCALE: u32 = 0x2A_D7B1;
31	const DURATION: u32 = 0x4489;
32	const MUXING_APP: u32 = 0x4D80;
33	const WRITING_APP: u32 = 0x5741;
34	pub(crate) const TRACKS: u32 = 0x1654_AE6B;
35	const TRACK_ENTRY: u32 = 0xAE;
36	const TRACK_NUMBER: u32 = 0xD7;
37	const TRACK_UID: u32 = 0x73C5;
38	const TRACK_TYPE: u32 = 0x83;
39	const FLAG_LACING: u32 = 0x9C;
40	const CODEC_ID: u32 = 0x86;
41	const CODEC_PRIVATE: u32 = 0x63A2;
42	const DEFAULT_DURATION: u32 = 0x23_E383;
43	const CODEC_DELAY: u32 = 0x56AA;
44	const SEEK_PRE_ROLL: u32 = 0x56BB;
45	const VIDEO: u32 = 0xE0;
46	const PIXEL_WIDTH: u32 = 0xB0;
47	const PIXEL_HEIGHT: u32 = 0xBA;
48	const COLOUR: u32 = 0x55B0;
49	const MATRIX_COEFFICIENTS: u32 = 0x55B1;
50	const BITS_PER_CHANNEL: u32 = 0x55B2;
51	const RANGE: u32 = 0x55B9;
52	const TRANSFER_CHARACTERISTICS: u32 = 0x55BA;
53	const PRIMARIES: u32 = 0x55BB;
54	const MAX_CLL: u32 = 0x55BC;
55	const MAX_FALL: u32 = 0x55BD;
56	const MASTERING_METADATA: u32 = 0x55D0;
57	const PRIMARY_R_X: u32 = 0x55D1;
58	const PRIMARY_R_Y: u32 = 0x55D2;
59	const PRIMARY_G_X: u32 = 0x55D3;
60	const PRIMARY_G_Y: u32 = 0x55D4;
61	const PRIMARY_B_X: u32 = 0x55D5;
62	const PRIMARY_B_Y: u32 = 0x55D6;
63	const WHITE_POINT_X: u32 = 0x55D7;
64	const WHITE_POINT_Y: u32 = 0x55D8;
65	const LUMINANCE_MAX: u32 = 0x55D9;
66	const LUMINANCE_MIN: u32 = 0x55DA;
67	const AUDIO: u32 = 0xE1;
68	const SAMPLING_FREQUENCY: u32 = 0xB5;
69	const CHANNELS: u32 = 0x9F;
70	pub(crate) const CHAPTERS: u32 = 0x1043_A770;
71	const EDITION_ENTRY: u32 = 0x45B9;
72	const EDITION_UID: u32 = 0x45BC;
73	const CHAPTER_ATOM: u32 = 0xB6;
74	const CHAPTER_UID: u32 = 0x73C4;
75	const CHAPTER_TIME_START: u32 = 0x91;
76	const CHAPTER_TIME_END: u32 = 0x92;
77	const CHAPTER_DISPLAY: u32 = 0x80;
78	const CHAP_STRING: u32 = 0x85;
79	const CHAP_LANGUAGE: u32 = 0x437C;
80	pub(crate) const CLUSTER: u32 = 0x1F43_B675;
81	pub(crate) const TIMESTAMP: u32 = 0xE7;
82	pub(crate) const SIMPLE_BLOCK: u32 = 0xA3;
83	pub(crate) const BLOCK_GROUP: u32 = 0xA0;
84	const BLOCK: u32 = 0xA1;
85	const DISCARD_PADDING: u32 = 0x75A2;
86	pub(crate) const CUES: u32 = 0x1C53_BB6B;
87	const CUE_POINT: u32 = 0xBB;
88	const CUE_TIME: u32 = 0xB3;
89	const CUE_TRACK_POSITIONS: u32 = 0xB7;
90	const CUE_TRACK: u32 = 0xF7;
91	const CUE_CLUSTER_POSITION: u32 = 0xF1;
