93	/// The eight-byte "unknown" size, written where a size is patched later.
94	pub(crate) const UNKNOWN_SIZE: [u8; 8] = [0x01, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF];
95	
96	// ---- encoders --------------------------------------------------------------
97	
98	/// An element ID's bytes: its big-endian value without leading zero bytes.
99	pub(crate) fn id(id: u32) -> Vec<u8> {
100	    let bytes = id.to_be_bytes();
101	    let first = bytes.iter().position(|b| *b != 0).unwrap_or(3);
102	    bytes[first..].to_vec()
103	}
104	
105	/// A size as the shortest vint that holds it; each length's all-ones value
106	/// is "unknown", so it is never used for a known size.
107	pub(crate) fn vint(n: u64) -> Vec<u8> {
108	    let Some(len) = (1..8usize).find(|len| n < (1u64 << (7 * len)) - 1) else {
109	        return size8(n).to_vec();
110	    };
111	    let mut out = n.to_be_bytes()[8 - len..].to_vec();
112	    out[0] |= 0x80 >> (len - 1);
113	    out
114	}
115	
116	/// A size as an eight-byte vint, the form a patched size is written in.
117	/// Sizes past 2^56 − 2 do not occur: a file that large cannot be written.
118	pub(crate) fn size8(n: u64) -> [u8; 8] {
119	    let mut out = (n.min((1u64 << 56) - 2)).to_be_bytes();
120	    out[0] = 0x01;
121	    out
122	}
123	
124	/// An element with `body` as its data.
125	pub(crate) fn binary(id_value: u32, body: &[u8]) -> Vec<u8> {
126	    let mut out = id(id_value);
127	    out.extend(vint(body.len() as u64));
128	    out.extend_from_slice(body);
129	    out
130	}
131	
132	/// A master element holding `children` in order.
133	pub(crate) fn master(id_value: u32, children: &[Vec<u8>]) -> Vec<u8> {
134	    binary(id_value, &children.concat())
135	}
136	
137	/// An unsigned integer in the fewest bytes (at least one).
138	pub(crate) fn uint(id_value: u32, v: u64) -> Vec<u8> {
139	    let bytes = v.to_be_bytes();
140	    let first = bytes.iter().position(|b| *b != 0).unwrap_or(7);
141	    binary(id_value, &bytes[first..])
142	}
143	
144	/// A signed integer in the fewest bytes that keep its sign.
145	pub(crate) fn int(id_value: u32, v: i64) -> Vec<u8> {
146	    let bytes = v.to_be_bytes();
147	    // A leading byte is redundant when it is all sign and the next keeps it.
148	    let sign = |i: usize| (bytes[i] == 0 || bytes[i] == 0xFF) && (bytes[i] ^ bytes[i + 1]) < 0x80;
149	    let first = (0..7).find(|i| !sign(*i)).unwrap_or(7);
150	    binary(id_value, &bytes[first..])
151	}
152	
153	/// A float as eight bytes, so a value read back is the value written.
154	pub(crate) fn float(id_value: u32, v: f64) -> Vec<u8> {
155	    binary(id_value, &v.to_be_bytes())
156	}
157	
158	pub(crate) fn string(id_value: u32, s: &str) -> Vec<u8> {
159	    binary(id_value, s.as_bytes())
160	}
161	
162	/// A Void element exactly `total` bytes long (at least 2).
163	pub(crate) fn void(total: usize) -> Vec<u8> {
164	    let (head, body) = if total >= 2 && total - 2 < 127 {
165	        (vec![VOID as u8, 0x80 | (total - 2) as u8], total - 2)
166	    } else {
167	        let body = total.saturating_sub(9);
168	        let mut head = vec![VOID as u8];
169	        head.extend(size8(body as u64));
170	        (head, body)
171	    };
172	    let mut out = head;
173	    out.resize(out.len() + body, 0);
174	    out
175	}
176	
177	// ---- builders --------------------------------------------------------------
178	
179	/// The EBML header: DocType `webm`, DocTypeVersion 4, DocTypeReadVersion 2.
180	pub(crate) fn ebml_header() -> Vec<u8> {
181	    master(
182	        EBML,
183	        &[
184	            uint(EBML_VERSION, 1),
185	            uint(EBML_READ_VERSION, 1),
186	            uint(EBML_MAX_ID_LENGTH, 4),
187	            uint(EBML_MAX_SIZE_LENGTH, 8),
188	            string(DOC_TYPE, "webm"),
189	            uint(DOC_TYPE_VERSION, 4),
190	            uint(DOC_TYPE_READ_VERSION, 2),
191	        ],
192	    )
193	}
194	
195	/// Info: millisecond timestamps, the duration in them, and the app's name.
196	pub(crate) fn info(duration_ns: u64) -> Vec<u8> {
197	    master(
198	        INFO,
199	        &[
200	            uint(TIMESTAMP_SCALE, 1_000_000),
201	            float(DURATION, duration_ns as f64 / 1e6),
202	            string(MUXING_APP, "Frame Job"),
203	            string(WRITING_APP, "Frame Job"),
204	        ],
205	    )
206	}
207	
208	/// The video track's Colour: CICP, range and depth, and on HDR10 the light
209	/// levels and the mastering display.
210	pub(crate) struct ColourOut {
211	    pub matrix: u8,
212	    pub range: u8,
213	    pub transfer: u8,
214	    pub primaries: u8,
215	    pub bits: u8,
216	    pub light: Option<(u64, u64)>,
217	    pub mastering: Option<Mastering>,
218	}
219	
220	/// The video TrackEntry (number 1, UID 1).
221	pub(crate) fn video_entry(
222	    private: &[u8],
223	    width: u32,
224	    height: u32,
225	    default_duration_ns: u64,
226	    colour: &ColourOut,
227	) -> Vec<u8> {
228	    let mut c = vec![
229	        uint(MATRIX_COEFFICIENTS, colour.matrix.into()),
230	        uint(BITS_PER_CHANNEL, colour.bits.into()),
231	        uint(RANGE, colour.range.into()),
232	        uint(TRANSFER_CHARACTERISTICS, colour.transfer.into()),
233	        uint(PRIMARIES, colour.primaries.into()),
234	    ];
235	    if let Some((cll, fall)) = colour.light {
236	        c.push(uint(MAX_CLL, cll));
237	        c.push(uint(MAX_FALL, fall));
238	    }
