    let profile = if sdr { 0 } else { 2 };
    for k in 0..60 {
        let key = k % 30 == 0;
        w.add(V, frame_ns(k, 30, 1), key, 0, &vp9_frame(k, profile, key))
            .expect("video");
    }
    for k in 0..100 {
        w.add(A, k as i64 * 20_000_000, true, 0, &opus(k))
            .expect("audio");
    }
    w.end(V).expect("end video");
    w.end(A).expect("end audio");
    w.finish().expect("finish");
}
