import CoreVideo
import Metal
import MetalPerformanceShaders

/// One picture for SVT-AV1: 10-bit planar 4:2:0 in one shared buffer (spec §11 CX-14 (3)) —
/// luma, then Cb at `cbOffset`, then Cr at `crOffset`, each row `lumaStride` or
/// `chromaStride` samples. Strides and offsets count 16-bit samples, each holding its 10 bits
/// in the low bits, little-endian (yuv420p10le).
struct I010Frame {
    let buffer: MTLBuffer
    let width: Int
    let height: Int
    let lumaStride: Int
    let chromaStride: Int
    let cbOffset: Int
    let crOffset: Int
}

/// `ExportI010.metal`'s uniforms, field for field; strides and offsets in samples.
private struct ExportI010Uniforms {
    var width: UInt32
    var height: UInt32
    var lumaStride: UInt32
    var chromaStride: UInt32
    var cbOffset: UInt32
    var crOffset: UInt32
    var kr: Float
    var kb: Float
}

/// The compositor's 64RGBAHalf frames as video-range I010 for the `av1` row (spec §11
/// CX-12 (5), CX-14 (3)), through the picture's matrix (`ExportAV1Picture.lumaWeights`), on
/// the GPU: `MPSImageLanczosScale` to the export size when it is not the canvas — the
/// picture fitted inside with black bars, or filling a frame within a pixel of the canvas's
/// shape (`fills`, G-33 (c)) — then `framejob_export_i010`.
///
/// Called on the export's video queue alone; the planes come from a pool the encode queue
/// gives back through `recycle` once SVT has copied them.
final class ExportI010Converter {
    let width: Int
    let height: Int

    private let device: MTLDevice
    private let queue: MTLCommandQueue
    private let pipeline: MTLComputePipelineState
    private let cache: CVMetalTextureCache
    /// The scaler, its transform and clip, and the export-size texture it writes; nil when
    /// the export is at the canvas size.
    private let scaler: MPSImageLanczosScale?
    private let scaled: MTLTexture?
    private var transform = MPSScaleTransform(scaleX: 1, scaleY: 1, translateX: 0, translateY: 0)
    private let weights: (kr: Float, kb: Float)
    /// In samples.
    private let lumaStride: Int
    private let chromaStride: Int
    /// In bytes: two per sample.
    private let length: Int

    private let lock = NSLock()
    private var pool: [I010Frame] = []

    init(
        width: Int, height: Int, canvas: CGSize, fills: Bool, picture: ExportAV1Picture,
        pool count: Int
    ) throws {
        func failure(_ what: String) -> Exporter.ExportError {
            .failed("The frames could not be prepared for the AV1 encoder: \(what).")
        }
        guard let device = MTLCreateSystemDefaultDevice(), let queue = device.makeCommandQueue()
        else { throw failure("no Metal device") }
        guard let library = (try? device.makeDefaultLibrary(bundle: Bundle.main))
            ?? device.makeDefaultLibrary(),
            let function = library.makeFunction(name: "framejob_export_i010"),
            let pipeline = try? device.makeComputePipelineState(function: function)
        else { throw failure("the conversion kernel is missing") }
        var cache: CVMetalTextureCache?
        guard CVMetalTextureCacheCreate(kCFAllocatorDefault, nil, device, nil, &cache)
            == kCVReturnSuccess, let cache
        else { throw failure("no texture cache") }
        self.width = width
        self.height = height
        self.device = device
        self.queue = queue
        self.pipeline = pipeline
        self.cache = cache
        weights = picture.lumaWeights
        lumaStride = width
        chromaStride = (width + 1) / 2
        length = 2 * (lumaStride * height + 2 * chromaStride * ((height + 1) / 2))

        let canvasWidth = Int(canvas.width.rounded())
        let canvasHeight = Int(canvas.height.rounded())
        if canvasWidth == width && canvasHeight == height || canvasWidth < 1 || canvasHeight < 1 {
            scaler = nil
            scaled = nil
        } else {
            let made = try Self.scaling(
                device: device, size: (width, height), canvas: canvas, fills: fills)
            scaler = made.scaler
            scaled = made.texture
            transform = made.transform
        }
        for _ in 0..<max(1, count) {
            pool.append(try makeFrame())
        }
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportI010Converter does not support NSCoder")
    }

    /// The Lanczos scaler, its transform and clip, and a destination cleared to black once:
    /// a fit writes only the picture's rectangle, so the bars stay black on every frame.
    private static func scaling(
        device: MTLDevice, size: (Int, Int), canvas: CGSize, fills: Bool
    ) throws -> (scaler: MPSImageLanczosScale, texture: MTLTexture, transform: MPSScaleTransform) {
        let (w, h) = (Double(size.0), Double(size.1))
        let (cw, ch) = (Double(canvas.width), Double(canvas.height))
        let s = fills ? max(w / cw, h / ch) : min(w / cw, h / ch)
        let (pw, ph) = (cw * s, ch * s)
        let transform = MPSScaleTransform(
            scaleX: s, scaleY: s, translateX: (w - pw) / 2, translateY: (h - ph) / 2)
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: .rgba16Float, width: size.0, height: size.1, mipmapped: false)
        descriptor.usage = [.shaderRead, .shaderWrite]
        descriptor.storageMode = .shared
        guard let texture = device.makeTexture(descriptor: descriptor) else {
            throw Exporter.ExportError.failed(
                "The frames could not be prepared for the AV1 encoder: no scaling texture.")
        }
        let zeros = [UInt16](repeating: 0, count: size.0 * size.1 * 4)
        texture.replace(
            region: MTLRegionMake2D(0, 0, size.0, size.1), mipmapLevel: 0, withBytes: zeros,
            bytesPerRow: size.0 * 8)
        let scaler = MPSImageLanczosScale(device: device)
        if !fills {
            let x = max(0, Int(((w - pw) / 2).rounded()))
            let y = max(0, Int(((h - ph) / 2).rounded()))
            scaler.clipRect = MTLRegionMake2D(
                x, y, min(size.0 - x, Int(pw.rounded())), min(size.1 - y, Int(ph.rounded())))
        }
        return (scaler, texture, transform)
    }

    private func makeFrame() throws -> I010Frame {
        guard let buffer = device.makeBuffer(length: length, options: .storageModeShared) else {
            throw Exporter.ExportError.failed(
                "The frames could not be prepared for the AV1 encoder: no plane buffer.")
        }
        let chromaSamples = chromaStride * ((height + 1) / 2)
        return I010Frame(
            buffer: buffer, width: width, height: height, lumaStride: lumaStride,
            chromaStride: chromaStride, cbOffset: lumaStride * height,
            crOffset: lumaStride * height + chromaSamples)
    }

    /// One frame converted, waiting for the GPU; nil when it could not be wrapped or the
    /// GPU failed.
    func convert(_ frame: CVPixelBuffer) -> I010Frame? {
        guard let source = wrap(frame), let texture = CVMetalTextureGetTexture(source),
            let out = take(), let commands = queue.makeCommandBuffer()
        else { return nil }
        var input = texture
        if let scaler, let scaled {
            withUnsafePointer(to: &transform) { pointer in
                scaler.scaleTransform = pointer
                scaler.encode(
                    commandBuffer: commands, sourceTexture: texture, destinationTexture: scaled)
                scaler.scaleTransform = nil
            }
            input = scaled
        }
        guard let encoder = commands.makeComputeCommandEncoder() else {
            recycle(out)
            return nil
        }
        var uniforms = ExportI010Uniforms(
            width: UInt32(width), height: UInt32(height), lumaStride: UInt32(lumaStride),
            chromaStride: UInt32(chromaStride), cbOffset: UInt32(out.cbOffset),
            crOffset: UInt32(out.crOffset), kr: weights.kr, kb: weights.kb)
        encoder.setComputePipelineState(pipeline)
        encoder.setTexture(input, index: 0)
        encoder.setBuffer(out.buffer, offset: 0, index: 0)
        encoder.setBytes(&uniforms, length: MemoryLayout<ExportI010Uniforms>.stride, index: 1)
        let group = MTLSize(width: 16, height: 16, depth: 1)
        let blocks = MTLSize(width: (width + 1) / 2, height: (height + 1) / 2, depth: 1)
        encoder.dispatchThreads(blocks, threadsPerThreadgroup: group)
        encoder.endEncoding()
        commands.commit()
        commands.waitUntilCompleted()
        withExtendedLifetime(source) {}
        guard commands.status == .completed else {
            recycle(out)
            return nil
        }
        return out
    }

    /// Gives a frame's planes back to the pool.
    func recycle(_ frame: I010Frame) {
        lock.lock()
        pool.append(frame)
        lock.unlock()
    }

    private func take() -> I010Frame? {
        lock.lock()
        let frame = pool.popLast()
        lock.unlock()
        return frame ?? (try? makeFrame())
    }

    /// The frame as a Metal texture over the same IOSurface.
    private func wrap(_ frame: CVPixelBuffer) -> CVMetalTexture? {
        CVMetalTextureCacheFlush(cache, 0)
        var wrapper: CVMetalTexture?
        let status = CVMetalTextureCacheCreateTextureFromImage(
            kCFAllocatorDefault, cache, frame, nil, .rgba16Float,
            CVPixelBufferGetWidth(frame), CVPixelBufferGetHeight(frame), 0, &wrapper)
        return status == kCVReturnSuccess ? wrapper : nil
    }
}
//
//  ExportI010.metal — the `av1` row's frames for SVT-AV1 (spec §11 CX-12 (5),
//  CX-14 (3)): a compositor frame (64RGBAHalf, premultiplied, in the encoding
//  of the picture the export writes) converted to video-range 10-bit I010 in
//  three planes of one buffer, each sample 16 bits, little-endian, the 10 bits
//  in its low bits (yuv420p10le). Owned by `app/Sources/ExportI010.swift`,
//  which scales the frame to the export size first when it is not the canvas.
//
//  One thread per 2 × 2 block: it writes the block's four luma samples and
//  one Cb and one Cr, the mean of the four pixels' (a 2 × 2 box, the chroma
//  siting SVT's sequence header leaves unspecified). RGB is clamped to 0…1 and
//  read as it is, premultiplied, so a transparent canvas lands on black as it
//  does through VideoToolbox on `h264`.
//
//  The matrix is the picture's (`kr`, `kb`: BT.709's or BT.2020's):
//  Y′ = kr R + (1 − kr − kb) G + kb B; Cb′ = (B − Y′) / (2 (1 − kb));
//  Cr′ = (R − Y′) / (2 (1 − kr)); Y = round(64 + 876 Y′);
//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean.
//

#include <metal_stdlib>
using namespace metal;

/// Mirrored by `ExportI010Uniforms` in `ExportI010.swift`; every field 32 bits.
/// Strides and offsets are in samples.
struct ExportI010Uniforms {
    uint width;
    uint height;
    uint lumaStride;
    uint chromaStride;
    uint cbOffset;
    uint crOffset;
    float kr;
    float kb;
};

kernel void framejob_export_i010(texture2d<half, access::read> src [[texture(0)]],
                                 device ushort *planes [[buffer(0)]],
                                 constant ExportI010Uniforms &u [[buffer(1)]],
                                 uint2 gid [[thread_position_in_grid]]) {
    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
        return;
    }
    const float3 weights = float3(u.kr, 1.0 - u.kr - u.kb, u.kb);
    const float cbScale = 2.0 * (1.0 - u.kb);
    const float crScale = 2.0 * (1.0 - u.kr);
    float cb = 0.0;
    float cr = 0.0;
    float count = 0.0;
    for (uint dy = 0; dy < 2; dy++) {
        for (uint dx = 0; dx < 2; dx++) {
            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
            if (at.x >= u.width || at.y >= u.height) {
                continue;
            }
            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
            float luma = dot(rgb, weights);
            planes[at.y * u.lumaStride + at.x] = ushort(round(64.0 + 876.0 * luma));
            cb += (rgb.b - luma) / cbScale;
            cr += (rgb.r - luma) / crScale;
            count += 1.0;
        }
    }
    uint chroma = gid.y * u.chromaStride + gid.x;
    planes[u.cbOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cb / count), 0.0, 1023.0));
    planes[u.crOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cr / count), 0.0, 1023.0));
}
import CoreMedia

/// The picture the `av1` row writes (spec §11 CX-14): the SDR version or BT.709 (`sdr`), the
/// HLG master (`hlg`) or HDR10 (`pq`), read from the settings' `color` — which the core writes
/// only in an HLG project, so an SDR project is `.sdr`.
///
/// One value carries everything the three places that label the picture need, so they cannot
/// disagree: the luma weights `ExportI010.metal` converts with (CX-14 (3)), the CICP SVT-AV1
/// writes into the sequence header and the `colr` the `av01` entry carries (CX-14 (4)), and on
/// PQ alone HD-5's fixed HDR10 metadata, both as SVT's metadata OBUs and as the entry's
/// `mdcv`/`clli` (CX-14 (5)).
enum ExportAV1Picture: Equatable {
    case sdr, hlg, pq

    /// `hlg` and `pq` as named; anything else, absent included, is `.sdr`.
    init(color: String?) {
        switch color {
        case "hlg": self = .hlg
        case "pq": self = .pq
        default: self = .sdr
        }
    }

    /// The sequence header's `color_primaries`: BT.709, or BT.2020 for an HDR picture.
    var primaries: EbColorPrimaries {
        self == .sdr ? EB_CICP_CP_BT_709 : EB_CICP_CP_BT_2020
    }

    /// The sequence header's `transfer_characteristics`.
    var transfer: EbTransferCharacteristics {
        switch self {
        case .sdr: return EB_CICP_TC_BT_709
        case .hlg: return EB_CICP_TC_HLG
        case .pq: return EB_CICP_TC_SMPTE_2084
        }
    }

    /// The sequence header's `matrix_coefficients`: BT.709, or BT.2020 non-constant luminance.
    var matrix: EbMatrixCoefficients {
        self == .sdr ? EB_CICP_MC_BT_709 : EB_CICP_MC_BT_2020_NCL
    }

    /// The matrix's (Kr, Kb), the weights the kernel derives Y′, Cb′ and Cr′ from.
    var lumaWeights: (kr: Float, kb: Float) {
        self == .sdr ? (0.2126, 0.0722) : (0.2627, 0.0593)
    }

    /// The format description's colour extensions — the `colr` box, video range — and on PQ
    /// HD-5's mastering display and content light level (`OutputTransform`'s blobs, the `mdcv`
    /// and `clli` boxes).
    var formatExtensions: [String: Any] {
        var out: [String: Any] = [
            kCMFormatDescriptionExtension_ColorPrimaries as String: self == .sdr
                ? kCMFormatDescriptionColorPrimaries_ITU_R_709_2
                : kCMFormatDescriptionColorPrimaries_ITU_R_2020,
            kCMFormatDescriptionExtension_YCbCrMatrix as String: self == .sdr
                ? REDACTED
                : REDACTED,
            kCMFormatDescriptionExtension_FullRangeVideo as String: false,
        ]
        switch self {
        case .sdr:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        case .hlg:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        case .pq:
            out[kCMFormatDescriptionExtension_TransferFunction as String] =
                REDACTED
        }
        if carriesHDR10 {
            out[kCMFormatDescriptionExtension_MasteringDisplayColorVolume as String] =
                OutputTransform.masteringDisplay
            out[kCMFormatDescriptionExtension_ContentLightLevelInfo as String] =
                OutputTransform.contentLightLevel
        }
        return out
    }

    /// Whether HD-5's HDR10 metadata is written: on PQ alone.
    var carriesHDR10: Bool {
        self == .pq
    }

    /// `OutputTransform.masteringDisplay` in the form `svt_aom_parse_mastering_display` reads:
    /// P3's green, blue and red primaries and D65 as x, y, then the maximum and minimum
    /// luminance in cd/m².
    static let masteringDisplay =
        "G(0.265,0.690)B(0.150,0.060)R(0.680,0.320)WP(0.3127,0.3290)L(1000,0.005)"

    /// `OutputTransform.contentLightLevel` in the form `svt_aom_parse_content_light_level`
    /// reads: MaxCLL, MaxFALL.
    static let contentLightLevel = "1000,0"
}
