#!/usr/bin/env python3
"""Codec export C1 fix pass (spec §11 CX-13): calibrate SVT-AV1's capped CRF
against HEVC on the spike's three 8-bit 1080p clips.

crf.py hevc                 HEVC (VideoToolbox, as run.py asks it) at each calibration rate
crf.py sweep                SVT-AV1 at presets 8/6/4, CRF 18..46 step 2, uncapped
crf.py verify [--overshoot N] P:TIER:CRF...
                            SVT-AV1 at preset P, capped at the tier's rate, at CRF
                            (`--mbr-overshoot-pct` N; SVT's default 50 when absent)
crf.py table                the CRF each preset needs at each rate (from hevc + sweep)
crf.py sweep-owner          SVT-AV1 at presets 8/6/4, CRF 14..32 step 2, uncapped, on the
                            owner's IMG_0018.MOV as Frame Job composes it (media/owner-ref.mov,
                            av1_export_proof.py R's ProRes 422 reference, piped as 8-bit 4:2:0)
crf.py owner-hevc SOCKET    Frame Job's own `hevc` export of that project at each rate, through
                            a running instance's socket, scored against the same reference

Every encode appends one JSON line to crf.jsonl (VMAF/PSNR/SSIM by ffmpeg's
libvmaf against the y4m, as run.py does).
"""
import json, os, subprocess, sys, time

S = "/Users/kevingalligan/devel/framejob-codecs/tools/proof/work/codec-spike"
SVT = f"{S}/src/svt-av1/Bin/Release/SvtAv1EncApp"
OUT = f"{S}/out-crf"
LOG = f"{S}/crf.jsonl"
FRAMES = 150
CLIPS = {"gh5": 25, "promo": 30, "real8": 30}
OWNER_REF = f"{S}/media/owner-ref.mov"
OWNER_FRAMES = 1658
# Bits per pixel per frame at 1920 × 1080 × 30 of the sheet's tiers (rounded to 100 kbps,
# ExportSheetOptions.QualityTier with AV1's 0.6) and "Format default" (0.07).
RATES = {"low": 2_400_000, "medium": 3_600_000, "default": 4_354_560, "high": 4_800_000,
         "maximum": 7_200_000}
BPP = {k: v / (1920 * 1080 * 30) for k, v in RATES.items()}
PRESETS = (8, 6, 4)
CRFS = range(18, 47, 2)


def rate(clip, tier):
    return round(BPP[tier] * 1920 * 1080 * CLIPS[clip])


def vmaf(dist, ref, tag):
    log = f"{OUT}/{tag}.vmaf.json"
    lavfi = ("[0:v]format=yuv420p,setpts=PTS-STARTPTS[d];[1:v]format=yuv420p,setpts=PTS-STARTPTS[r];"
             f"[d][r]libvmaf=log_fmt=json:log_path={log}:n_threads=12:"
             "feature=name=psnr|name=float_ssim")
    subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-i", dist, "-i", ref,
                    "-lavfi", lavfi, "-f", "null", "-"], check=True)
    pooled = json.load(open(log))["pooled_metrics"]
    return {"vmaf": round(pooled["vmaf"]["mean"], 3), "vmaf_min": round(pooled["vmaf"]["min"], 2),
            "psnr_y": round(pooled["psnr_y"]["mean"], 3),
            "float_ssim": round(pooled["float_ssim"]["mean"], 5)}


def encode(row, c, out, src, fps, frames=FRAMES, shell=False):
    t0 = time.time()
    p = subprocess.run(c, capture_output=True, text=True, shell=shell)
    if p.returncode != 0:
        raise SystemExit(f"FAILED {c if shell else ' '.join(c)}\n{p.stderr[-2000:]}")
    wall = time.time() - t0
    size = os.path.getsize(out)
    row |= {"wall_s": round(wall, 2), "bytes": size,
            "actual_bps": round(size * 8 / (frames / fps))}
    row |= vmaf(out, src, os.path.basename(out).rsplit(".", 1)[0])
    with open(LOG, "a") as f:
        f.write(json.dumps(row) + "\n")
    print(json.dumps(row), flush=True)


def hevc():
    for clip, fps in CLIPS.items():
        src = f"{S}/media/{clip}.y4m"
        for tier in RATES:
            bps = rate(clip, tier)
            out = f"{OUT}/{clip}-hevc-{tier}.mp4"
            c = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", "-i", src, "-c:v",
                 "hevc_videotoolbox", "-b:v", str(bps), "-g", str(round(2 * fps)),
                 "-profile:v", "main", "-tag:v", "hvc1", out]
            encode({"kind": "hevc", "clip": clip, "tier": tier, "target_bps": bps}, c, out, src, fps)


def svt(clip, preset, crf, cap_bps=None, tier=None, overshoot=None):
    fps = CLIPS[clip]
    src = f"{S}/media/{clip}.y4m"
    tag = (f"{clip}-svt{preset}-crf{crf}" + (f"-cap-{tier}" if cap_bps else "")
           + (f"-os{overshoot}" if overshoot is not None else ""))
    out = f"{OUT}/{tag}.ivf"
    c = [SVT, "-i", src, "-b", out, "--preset", str(preset), "--rc", "0", "--crf", str(crf),
         "--keyint", str(round(2 * fps)), "--irefresh-type", "2", "--progress", "0"]
    if cap_bps:
        c += ["--mbr", str(round(cap_bps / 1000))]
    if overshoot is not None:
        c += ["--mbr-overshoot-pct", str(overshoot)]
    encode({"kind": "svt", "clip": clip, "preset": preset, "crf": crf, "cap_bps": cap_bps,
            "tier": tier, "overshoot": overshoot}, c, out, src, fps)


def svt_owner(preset, crf, cap_bps=None, tier=None, overshoot=None):
    tag = (f"owner-svt{preset}-crf{crf}" + (f"-cap-{tier}" if cap_bps else "")
           + (f"-os{overshoot}" if overshoot is not None else ""))
    out = f"{OUT}/{tag}.ivf"
    svt = (f"'{SVT}' -i stdin -b '{out}' --preset {preset} --rc 0 --crf {crf} --keyint 60 "
           "--irefresh-type 2 --progress 0")
    if cap_bps:
        svt += f" --mbr {round(cap_bps / 1000)}"
    if overshoot is not None:
        svt += f" --mbr-overshoot-pct {overshoot}"
    c = (f"ffmpeg -hide_banner -loglevel error -i '{OWNER_REF}' -an -sws_dither none -pix_fmt yuv420p "
         f"-f yuv4mpegpipe -strict -1 - | {svt}")
    encode({"kind": "svt", "clip": "owner", "preset": preset, "crf": crf, "cap_bps": cap_bps,
            "tier": tier, "overshoot": overshoot}, c, out, OWNER_REF, 30, OWNER_FRAMES, True)


def owner_hevc(socket):
    sys.path.insert(0, f"{S}/../..")
    import mcp
    client = mcp.MCP(socket, timeout=900)
    project = f"{OUT}/owner-hevc.framejob"
    client.call("new_project", path=project)
    call = lambda tool, **a: client.call_with(tool, {"project": project, **a})
    try:
        media = call("import_media", path=f"{S}/../../media/owner-sync/IMG_0018.MOV")["media"]
        track = call("get_project")["project"]["tracks"][0]["id"]
        call("add_clip", track=track, media=media, at=0)
        for tier, bps in RATES.items():
            out = f"{OUT}/owner-fjhevc-{tier}.mp4"
            if os.path.exists(out):
                os.unlink(out)
            extra = {} if tier == "default" else {"video_bitrate": bps}
            t0 = time.time()
            client.export_with({"project": project, "path": out, "preset": "hevc", **extra})
            row = {"kind": "hevc", "clip": "owner", "tier": tier, "target_bps": bps,
                   "wall_s": round(time.time() - t0, 2), "bytes": os.path.getsize(out)}
            probe = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0",
                                    "-show_entries", "stream=bit_rate", "-of", "csv=p=0", out],
                                   capture_output=True, text=True)
            row["actual_bps"] = int(probe.stdout.strip() or 0)
            row |= vmaf(out, OWNER_REF, f"owner-fjhevc-{tier}")
            with open(LOG, "a") as f:
                f.write(json.dumps(row) + "\n")
            print(json.dumps(row), flush=True)
    finally:
        call("close_project", discard=True)


def rows():
    return [json.loads(line) for line in open(LOG)] if os.path.exists(LOG) else []


def table():
    got = rows()
    target = {(r["clip"], r["tier"]): r["vmaf"] for r in got if r["kind"] == "hevc"}
    sweep = [r for r in got if r["kind"] == "svt" and not r["cap_bps"]]
    print("HEVC VMAF at each rate: " + "; ".join(
        f"{c}/{t} {v}" for (c, t), v in sorted(target.items())))
    for preset in PRESETS:
        for tier in RATES:
            best = None
            for crf in sorted({r["crf"] for r in sweep if r["preset"] == preset}):
                at = {r["clip"]: r["vmaf"] for r in sweep if r["preset"] == preset and r["crf"] == crf}
                if len(at) == len(CLIPS) and all(at[c] >= target[(c, tier)] for c in CLIPS):
                    best = crf
            print(f"preset {preset} {tier} ({BPP[tier]:.4f} bpp): highest swept CRF meeting HEVC "
                  f"on every clip {best}")


def main():
    os.makedirs(OUT, exist_ok=True)
    what = sys.argv[1]
    if what == "hevc":
        hevc()
    elif what == "sweep":
        for preset in PRESETS:
            for crf in CRFS:
                for clip in CLIPS:
                    svt(clip, preset, crf)
    elif what == "verify":
        specs, overshoot = sys.argv[2:], None
        if specs[:1] == ["--overshoot"]:
            overshoot, specs = int(specs[1]), specs[2:]
        for spec in specs:
            preset, tier, crf = spec.split(":")
            for clip in CLIPS:
                svt(clip, int(preset), int(crf), rate(clip, tier), tier, overshoot)
    elif what == "sweep-owner":
        for preset in PRESETS:
            for crf in range(14, 33, 2):
                svt_owner(preset, crf)
    elif what == "owner-hevc":
        owner_hevc(sys.argv[2])
    elif what == "table":
        table()


if __name__ == "__main__":
    main()
