    c = [SVT, "-i", src, "-b", out, "--preset", str(preset), "--rc", "0", "--crf", str(crf),
         "--keyint", str(round(2 * fps)), "--irefresh-type", "2", "--progress", "0"]
    if cap_bps:
        c += ["--mbr", str(round(cap_bps / 1000))]
    if overshoot is not None:
        c += ["--mbr-overshoot-pct", str(overshoot)]
    encode({"kind": "svt", "clip": clip, "preset": preset, "crf": crf, "cap_bps": cap_bps,
            "tier": tier, "overshoot": overshoot}, c, out, src, fps)


def svt_owner(preset, crf, cap_bps=None, tier=None, overshoot=None):
    tag = (f"owner-svt{preset}-crf{crf}" + (f"-cap-{tier}" if cap_bps else "")
           + (f"-os{overshoot}" if overshoot is not None else ""))
    out = f"{OUT}/{tag}.ivf"
    svt = (f"'{SVT}' -i stdin -b '{out}' --preset {preset} --rc 0 --crf {crf} --keyint 60 "
           "--irefresh-type 2 --progress 0")
    if cap_bps:
        svt += f" --mbr {round(cap_bps / 1000)}"
    if overshoot is not None:
        svt += f" --mbr-overshoot-pct {overshoot}"
    c = (f"ffmpeg -hide_banner -loglevel error -i '{OWNER_REF}' -an -sws_dither none -pix_fmt yuv420p "
         f"-f yuv4mpegpipe -strict -1 - | {svt}")
    encode({"kind": "svt", "clip": "owner", "preset": preset, "crf": crf, "cap_bps": cap_bps,
            "tier": tier, "overshoot": overshoot}, c, out, OWNER_REF, 30, OWNER_FRAMES, True)


def owner_hevc(socket):
    sys.path.insert(0, f"{S}/../..")
    import mcp
    client = mcp.MCP(socket, timeout=900)
    project = f"{OUT}/owner-hevc.framejob"
    client.call("new_project", path=project)
    call = lambda tool, **a: client.call_with(tool, {"project": project, **a})
    try:
        media = call("import_media", path=f"{S}/../../media/owner-sync/IMG_0018.MOV")["media"]
        track = call("get_project")["project"]["tracks"][0]["id"]
        call("add_clip", track=track, media=media, at=0)
        for tier, bps in RATES.items():
            out = f"{OUT}/owner-fjhevc-{tier}.mp4"
            if os.path.exists(out):
                os.unlink(out)
            extra = {} if tier == "default" else {"video_bitrate": bps}
            t0 = time.time()
            client.export_with({"project": project, "path": out, "preset": "hevc", **extra})
            row = {"kind": "hevc", "clip": "owner", "tier": tier, "target_bps": bps,
                   "wall_s": round(time.time() - t0, 2), "bytes": os.path.getsize(out)}
            probe = subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0",
                                    "-show_entries", "stream=bit_rate", "-of", "csv=p=0", out],
                                   capture_output=True, text=True)
            row["actual_bps"] = int(probe.stdout.strip() or 0)
            row |= vmaf(out, OWNER_REF, f"owner-fjhevc-{tier}")
            with open(LOG, "a") as f:
                f.write(json.dumps(row) + "\n")
            print(json.dumps(row), flush=True)
    finally:
        call("close_project", discard=True)


def rows():
    return [json.loads(line) for line in open(LOG)] if os.path.exists(LOG) else []


def table():
    got = rows()
    target = {(r["clip"], r["tier"]): r["vmaf"] for r in got if r["kind"] == "hevc"}
    sweep = [r for r in got if r["kind"] == "svt" and not r["cap_bps"]]
    print("HEVC VMAF at each rate: " + "; ".join(
        f"{c}/{t} {v}" for (c, t), v in sorted(target.items())))
    for preset in PRESETS:
        for tier in RATES:
            best = None
            for crf in sorted({r["crf"] for r in sweep if r["preset"] == preset}):
                at = {r["clip"]: r["vmaf"] for r in sweep if r["preset"] == preset and r["crf"] == crf}
                if len(at) == len(CLIPS) and all(at[c] >= target[(c, tier)] for c in CLIPS):
                    best = crf
            print(f"preset {preset} {tier} ({BPP[tier]:.4f} bpp): highest swept CRF meeting HEVC "
                  f"on every clip {best}")


def main():
    os.makedirs(OUT, exist_ok=True)
    what = sys.argv[1]
    if what == "hevc":
        hevc()
    elif what == "sweep":
        for preset in PRESETS:
            for crf in CRFS:
                for clip in CLIPS:
                    svt(clip, preset, crf)
    elif what == "verify":
        specs, overshoot = sys.argv[2:], None
        if specs[:1] == ["--overshoot"]:
            overshoot, specs = int(specs[1]), specs[2:]
        for spec in specs:
            preset, tier, crf = spec.split(":")
            for clip in CLIPS:
                svt(clip, int(preset), int(crf), rate(clip, tier), tier, overshoot)
    elif what == "sweep-owner":
        for preset in PRESETS:
            for crf in range(14, 33, 2):
                svt_owner(preset, crf)
    elif what == "owner-hevc":
        owner_hevc(sys.argv[2])
    elif what == "table":
        table()


if __name__ == "__main__":
    main()
